// Formats the who_is_waiting_on_me answer into one short brief.
// Response shape (docs): { ok: true, result: { waitingOnYou: [...] } }
const first = $input.all()[0].json;
if (!first.ok) {
  return [{ json: { brief: 'HeyReagent call failed: ' + (first.message || first.error || 'unknown error') } }];
}
const waiting = (first.result && first.result.waitingOnYou) || [];
if (waiting.length === 0) {
  return [{ json: { brief: 'Morning brief: nobody is waiting on your reply. Inbox is clear.' } }];
}
const lines = waiting.map((p, i) => {
  const who = p.profileUrl || p.name || JSON.stringify(p);
  return (i + 1) + '. ' + who;
});
return [{ json: { brief: 'Morning brief: ' + waiting.length + ' people waiting on your reply:\n' + lines.join('\n') } }];
